ill-icon" :style="getMonsterIconStyle(skill)"></div><div class="fight-ground-monster-ready-skill-attribute" :style="getMonsterAttributeStyle(skill)"></div></div></template><template #default><div class="fight-ground-monster-ready-skill-text" style="font-size: 10px;color: #fff;max-width: 150px;">{{skill.text}}</div></template></el-popover></div><div class="fight-ground-monster-change-button-block"><div class="fight-ground-monster-change-button" @click="changeFunction('monster')" :style="functionType==='monster'?'background-color: #3391ff;':''">精灵</div><div class="fight-ground-monster-change-button" @click="changeFunction('item')" :style="functionType==='item'?'background-color: #3391ff;':''">物品</div><div style="clear: both"></div></div></div><div class="fight-ground-monster-useskill-block" v-if="isShowDialog" @click="isShowDialog=false"><div class="fight-ground-monster-useskill" @click.stop=""><div class="fight-ground-monster-useskill-for" v-for="(situation,index) in useSituation" @click="selectTarget(situation)"> <div class="fight-ground-monster-useskill-for-name">{{situation.data.name}}</div><div class="fight-ground-monster-useskill-for-mes">level:{{situation.data.level}}</div><div class="fight-ground-monster-useskill-for-mes">life:{{situation.data.life}}</div></div></div></div><div class="fight-ground-button-call" @click="callMonster()">召唤</div><div class="fight-ground-button-end" @click="endTrun()">结束</div><div class="fight-ground-button" @click="runAway()">逃跑</div></div>